<script setup>
import {ref,computed,watch,onMounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,download} from '../../services/api.js'
import AiDetails from './AiDetails.vue'
const props=defineProps({kind:{type:String,default:'usage'}}),route=useRoute(),router=useRouter()
const keys=['q','nodeId','groupId','reporterId','actorId','provider','model','operation','tool','from','to','outcome','category','confidence','mapped']
const labels={q:'Search',nodeId:'Node',groupId:'Node group',reporterId:'Reporter',actorId:'Actor',provider:'Provider',model:'Model',operation:'Operation',tool:'Tool',from:'From',to:'To',outcome:'Outcome / action',category:'Evidence category',confidence:'Confidence',mapped:'Node attribution'}
const primary=['q','nodeId','provider','outcome','from','to'],advanced=ref(keys.some(k=>!['q','nodeId','provider','outcome','from','to'].includes(k)&&route.query[k]))
const health=ref(null)
const draft=ref({}),result=ref({items:[],total:0,page:1,pages:1,summary:{}}),error=ref(''),loading=ref(false),nodes=ref([]),groups=ref([]),reporters=ref([]),actors=ref([]),detailId=ref(''),detailOpen=ref(false)
let sequence=0
const reported=computed(()=>props.kind==='usage'),limit=computed(()=>Number(route.query.limit)||25),sort=computed(()=>route.query.sort||'time'),order=computed(()=>route.query.order||'desc')
const choices=computed(()=>({actorId:actors.value.map(a=>[a.id,a.email]),nodeId:nodes.value.map(n=>[n.id,n.hostname]),groupId:groups.value.map(g=>[g.id,g.name]),reporterId:reporters.value.map(r=>[r.id,r.name]),outcome:(reported.value?['success','failure','cancelled','incomplete']:['allow','block','observed']).map(x=>[x,x]),category:(reported.value?['reported']:['observed','suspected','supporting']).map(x=>[x,x]),confidence:(reported.value?['reported']:['high','medium','low']).map(x=>[x,x]),mapped:[['mapped','Mapped'],['unmapped','Unmapped']]}))
const columns=computed(()=>reported.value?[['time','Time'],['node','Node / Actor'],['reporter','Reporter / Coverage'],['operation','Operation / Tool'],['provider','Provider / Host'],['model','Model'],['outcome','Outcome']]:[['time','Time'],['node','Node / Source'],['provider','Provider / Service'],['hostname','Hostname / IP'],['operation','Category / Confidence'],['outcome','Action']])
function query(){return new URLSearchParams(Object.entries(route.query).filter(([k,v])=>[...keys,'page','limit','sort','order'].includes(k)&&v!==''))}
async function load(){const current=++sequence;loading.value=true;error.value='';try{const [data,status]=await Promise.all([api(`/ai/${props.kind}?${query()}`),api('/ai/health')]);if(current===sequence){result.value=data;health.value=status}}catch(e){if(current===sequence)error.value=e.message}finally{if(current===sequence)loading.value=false}}
function sync(){draft.value=Object.fromEntries(keys.map(k=>{let value=route.query[k]||'';if(['from','to'].includes(k)&&value){const d=new Date(value);value=Number.isFinite(+d)?new Date(+d-d.getTimezoneOffset()*60000).toISOString().slice(0,16):''}return[k,value]}));if(route.query.detail){detailId.value=String(route.query.detail);detailOpen.value=true}load()}
function apply(){try{const q={tab:props.kind};for(const k of keys)if(draft.value[k])q[k]=['from','to'].includes(k)?new Date(draft.value[k]).toISOString():draft.value[k];q.limit=limit.value;router.replace({query:q})}catch{error.value='Enter valid filter dates.'}}
function change(patch){router.replace({query:{...route.query,...patch,detail:undefined}})}
function sorting(key){change({sort:key,order:sort.value===key&&order.value==='asc'?'desc':'asc',page:1})}
function open(row){detailId.value=row.id;detailOpen.value=true;router.replace({query:{...route.query,detail:row.id}})}
function close(value){detailOpen.value=value;if(!value&&route.query.detail)router.replace({query:{...route.query,detail:undefined}})}
async function exportRows(){try{await download(`/ai/${props.kind}/export?${query()}`,`ai-${props.kind}.json`)}catch(e){error.value=e.message}}
const time=value=>value?new Date(value).toLocaleString():'Unknown'
watch(()=>[route.query,props.kind],sync,{immediate:true})
onMounted(async()=>{try{const data=await Promise.all([api('/nodes'),api('/node-groups'),api('/ai/reporters?limit=1000'),api('/ai/actors')]);nodes.value=data[0];groups.value=data[1];reporters.value=data[2].items;actors.value=data[3].items}catch(e){error.value=e.message}})
defineExpose({refresh:load})
</script>
<template><div class="ai-section"><p v-if="health&&!health.settings.enabled" class="ai-note ai-card" role="status">AI metadata collection is paused in Administration.</p><p v-else-if="health&&(health.backfill.firewallRemaining+health.backfill.browserRemaining>0||health.backlog>0)" class="ai-note ai-card" role="status">Processing retained observations: {{(health.backfill.firewallRemaining+health.backfill.browserRemaining).toLocaleString()}} source rows remain · {{health.backlog}} queued updates. Refresh to see completed classifications.</p><p v-if="error" class="error-msg" role="alert">{{error}}</p><section class="ai-summary"><article><span>{{reported?'Reported operations':'Traffic observations'}}</span><strong>{{result.total.toLocaleString()}}</strong><small>Matching filters</small></article><article><span>Mapped nodes</span><strong>{{result.summary.nodes??0}}</strong><small>Unknown identities remain unmapped</small></article><article v-if="reported"><span>Reported tokens (input / output)</span><strong>{{result.summary.inputTokens?.toLocaleString()??'Unknown'}} / {{result.summary.outputTokens?.toLocaleString()??'Unknown'}}</strong><small>{{result.summary.operationsWithMetrics||0}} operations supplied metrics</small></article><article v-if="reported"><span>Reported costs</span><strong v-if="!result.summary.costs?.length">Unknown</strong><div v-for="c in result.summary.costs" :key="c.currency+c.source">{{c.amount}} {{c.currency}} · {{c.source}}</div><small>Partial reporting; currencies and sources stay separate</small></article></section><section class="panel glass"><div class="panel-title ai-toolbar"><h2>{{reported?'Reported usage':'Observed AI traffic'}}</h2><div class="ai-actions"><label class="ai-rows">Rows<select :value="limit" @change="change({limit:$event.target.value,page:1})"><option>25</option><option>50</option><option>100</option></select></label><button class="button secondary small" :disabled="!result.total" @click="exportRows">Export JSON</button></div></div><p class="ai-note" style="padding:1rem">{{result.summary.coverage||'Collection coverage is partial.'}} Reporting is metadata only. Provider login, updates and telemetry are supporting traffic.</p><form class="ai-filters" @submit.prevent="apply"><label v-for="key in keys" v-show="primary.includes(key)||advanced" :key="key">{{labels[key]}}<select v-if="choices[key]" v-model="draft[key]"><option value="">All</option><option v-for="[value,label] in choices[key]" :key="value" :value="value">{{label}}</option></select><input v-else v-model.trim="draft[key]" :type="['from','to'].includes(key)?'datetime-local':'text'" :maxlength="key==='q'?200:160"></label><div class="ai-actions ai-full"><button type="button" class="button secondary" :aria-expanded="advanced" @click="advanced=!advanced">{{advanced?'Fewer filters':'More filters'}}</button><button class="button primary" :disabled="loading">Apply filters</button><button type="button" class="button secondary" @click="router.replace({query:{tab:kind}})">Clear filters</button><button type="button" class="button secondary" :disabled="loading" @click="load">Refresh</button></div></form><div class="ai-scroll table-wrap" tabindex="0" aria-label="AI activity table; scroll horizontally for all columns"><table><thead><tr><th v-for="[key,label] in columns" :key="key" :aria-sort="sort===key?(order==='asc'?'ascending':'descending'):undefined"><button class="ai-sort" @click="sorting(key)">{{label}} {{sort===key?(order==='asc'?'↑':'↓'):'↕'}}</button></th><th v-if="reported">Tokens (in / out)</th><th>Details</th></tr></thead><tbody><tr v-for="row in result.items" :key="row.id" @click="open(row)"><td>{{time(row.observed_at)}}</td><td>{{row.node_hostname||'Unmapped'}}<small>{{reported?(row.actor_email||'Unknown actor'):row.source}}</small></td><template v-if="reported"><td>{{row.reporter_name}}<small>{{row.coverage}}</small></td><td>{{row.operation}}<small>{{row.tool||'No tool reported'}}</small></td><td>{{row.provider||'Unknown'}}<small>{{row.hostname||'Local or unreported host'}}</small></td><td>{{row.response_model||row.model||'Unknown'}}</td><td><span class="status" :class="row.outcome==='success'?'reachable':row.outcome==='failure'?'unreachable':'unknown'">{{row.outcome}}</span></td><td>{{row.input_tokens??'—'}} / {{row.output_tokens??'—'}}</td></template><template v-else><td>{{row.provider||'Unknown'}}<small>{{row.service||'Unknown service'}}</small></td><td>{{row.hostname||'Requested hostname unknown'}}<small>{{row.peer_ip||'Domain-only observation'}}</small></td><td>{{row.category}}<small>{{row.confidence}} confidence · {{row.role||'Unknown role'}}</small></td><td><span class="status" :class="row.action">{{row.action==='block'?'Blocked attempt':row.action}}</span></td></template><td><button class="ai-link" @click.stop="open(row)">View details</button></td></tr><tr v-if="!result.items.length"><td :colspan="reported?9:7">{{loading?'Loading…':'No AI activity matches these filters.'}}</td></tr></tbody></table></div><div class="ai-pagination"><span>{{result.total}} records · partial coverage</span><div class="ai-actions"><button class="button secondary small" :disabled="loading||result.page<=1" @click="change({page:result.page-1})">Previous</button><span>Page {{result.page}} / {{result.pages}}</span><button class="button secondary small" :disabled="loading||result.page>=result.pages" @click="change({page:result.page+1})">Next</button></div></div></section><AiDetails :model-value="detailOpen" :id="detailId" :kind="kind" @update:model-value="close"/></div></template>
<style scoped src="./ai.css"></style>
